{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Samidorphan, a morphinan sharing the 4,5-epoxymorphinan core, 14-hydroxy and 6-keto features with the query, has an absolute oral bioavailability of 68.6% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Pethidine, an N-methyl opioid with a basic tertiary amine, shows absolute oral bioavailability of 47-73% in humans, supporting high F for the N-methyl morphinan query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "LSD, a rigid polycyclic basic tertiary amine, has absolute oral bioavailability of about 81% in humans, indicating that rigid basic polycyclic amines can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Pentazocine, a benzomorphan opioid, has oral bioavailability of 18% in healthy subjects, just below the 20% threshold; this contradictory evidence is less transferable because of its phenolic OH and different N-substitution.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Meptazinol, an N-methyl azepine opioid, has absolute oral bioavailability of 8.69% in humans; this contradictory evidence is limited by its phenol and non-morphinan scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 3-methoxy-14-hydroxy-6-keto N-methyl morphinan (oxycodone-like). High-transfer analogues with the same morphinan or rigid basic amine architecture (samidorphan 69%, LSD 80%) and N-methyl opioid pethidine (47-73%) support high oral bioavailability. The low-F analogues (pentazocine 18%, meptazinol 8.7%) are less transferable because they contain phenolic OH and/or non-morphinan scaffolds; the 3-methyl ether blocks phenolic glucuronidation, favoring high F. Therefore predict high (F >= 20%).",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the query molecule in the supplied evidence; extrapolation relies on close analogues.",
    "Potential first-pass metabolism differences due to the 3-methoxy group versus phenolic analogues are inferred but not directly measured.",
    "No specific transporter or efflux data for the query molecule are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

